    HitResult, 
    Start, 
    End, 
    ECC_Visibility // You can use ECC_WorldStatic, ECC_WorldDynamic, etc.
);

if (bHit)
{
    // A hit occurred
    UE_LOG(LogTemp, Warning, TEXT("Hit at: %s"), *HitResult.Location.ToString());
    // You can access other properties like HitResult.ImpactNormal, HitResult.Actor, etc.
